import React, { Children, ReactElement, useState } from 'react';
import { renderChildren as defaultRenderChildren } from '@fiverr-private/ui_utils';
import { Container } from '@fiverr-private/layout_components';
import type { CollapsibleGroupProps, CollapsibleProps } from '../types';

const NO_OPENED_PANEL = -1;

const CollapsibleGroup = ({
  defaultExpandedIndex,
  children,
  renderChildren = defaultRenderChildren,
  dataTrackTag = 'collapsible_group',
  dataTrackValue,
}: CollapsibleGroupProps) => {
  const [expandedPanel, setExpandedPanel] = useState(defaultExpandedIndex);
  const childrenArray = Children.toArray(children) as ReactElement<CollapsibleProps>[];
  return (
    <Container dataTrackTag={dataTrackTag} dataTrackValue={dataTrackValue}>
      {Children.map(childrenArray, (child: ReactElement<CollapsibleProps>, index) =>
        renderChildren(child, {
          expanded: expandedPanel === index,
          paddingBottom: expandedPanel === index && index !== childrenArray.length - 1 ? '6' : undefined,
          key: index,
          onToggle: (expanded) => {
            if (expanded) {
              setExpandedPanel(index);
            } else if (index === expandedPanel) {
              setExpandedPanel(NO_OPENED_PANEL);
            }
            if (typeof child?.props?.onToggle === 'function') {
              child.props.onToggle(expanded);
            }
          },
        })
      )}
    </Container>
  );
};

CollapsibleGroup.displayName = 'CollapsibleGroup';

export default CollapsibleGroup;
